// Context ablation: replay the last question with one block of context taken
// out, and see whether the answer changes. A block whose removal changes the
// answer is one the answer relied on; one whose removal changes nothing was
// along for the ride.
//
// Everything here is pure; register.tsx makes the model calls.

import type { ContentBlock, Message } from './analyze'
import { estimateTokens, parse } from './analyze'

// One block of the conversation as the replay shows it to the model.
export type Segment = { id: string; label: string; tokens: number; text: string }

export type Replay = {
  // Everything before the question, in order.
  segments: Segment[]
  question: string
  // What the assistant actually said; shown in the pane, never sent.
  answer: string
}

export type TextBlock = { text: string; cache?: true }

const MIN_CANDIDATE_TOKENS = 200

// The API allows four cache marks per request; the replays use three, so a
// fourth stays free for whatever a provider adds.
const CACHE_MARKS = 3

const HEADER =
  'Below is the transcript of a coding session between a user and an AI assistant, ' +
  'including the tool calls the assistant made and what they returned.\n\n<transcript>\n'

const str = (value: unknown): string => (typeof value === 'string' ? value : '')

// Slash commands and their output come back as user text; they are no question.
const isCommandRecord = (text: string): boolean => /<command-name>|<local-command-/.test(text)

const resultBody = (content: unknown): string => {
  if (typeof content === 'string') return content
  if (!Array.isArray(content)) return ''
  return (content as ContentBlock[])
    .map(part => (part.type === 'text' ? str(part.text) : `[${part.type}]`))
    .join('\n')
}

const bodyOf = (part: ContentBlock): string => {
  if (part.type === 'text') return str(part.text)
  if (part.type === 'tool_use') return JSON.stringify(part.input ?? {})
  if (part.type === 'tool_result') return resultBody(part.content)
  return ''
}

// Splits the conversation at the last question that got an answer. Thinking,
// images and documents are left out of the replay: a text-only model call
// cannot carry them as the session did.
export const toReplay = (messages: readonly Message[]): Replay | undefined => {
  const { blocks } = parse(messages)
  const flat: { block: (typeof blocks)[number]; part: ContentBlock }[] = []
  let i = 0
  for (const message of messages) {
    for (const part of message.content) {
      if (!['text', 'thinking', 'tool_use', 'tool_result', 'image', 'document'].includes(part.type)) continue
      const block = blocks[i++]
      if (block) flat.push({ block, part })
    }
  }

  let questionAt = -1
  for (let k = flat.length - 1; k >= 0; k--) {
    const entry = flat[k]!
    if (entry.block.kind !== 'prompt' || isCommandRecord(bodyOf(entry.part))) continue
    const hasAnswer = flat.slice(k + 1).some(later => later.block.kind === 'reply')
    if (hasAnswer) {
      questionAt = k
      break
    }
  }
  if (questionAt < 0) return undefined

  const answer = flat
    .slice(questionAt + 1)
    .filter(entry => entry.block.kind === 'reply')
    .map(entry => bodyOf(entry.part))
    .join('\n')

  const segments = flat
    .slice(0, questionAt)
    .filter(entry => entry.block.kind !== 'thinking' && entry.block.kind !== 'media')
    .map(({ block, part }) => ({
      id: block.id,
      label: block.label,
      tokens: block.tokens,
      text: `[${block.label}]\n${bodyOf(part)}\n\n`,
    }))

  return { segments, question: bodyOf(flat[questionAt]!.part), answer }
}

// The blocks worth testing: the biggest ones, since they cost the most to keep.
export const pickCandidates = (replay: Replay, count: number): Segment[] =>
  [...replay.segments]
    .filter(segment => segment.tokens >= MIN_CANDIDATE_TOKENS)
    .sort((a, b) => b.tokens - a.tokens)
    .slice(0, count)

// Where the replays put their cache marks: just before the earliest candidates.
// Every replay sends the same text up to the block it removes, so a mark there
// lets the API serve that prefix from cache instead of billing it again.
export const cacheMarks = (replay: Replay, candidates: readonly Segment[]): number[] => {
  const position = new Map(replay.segments.map((segment, at) => [segment.id, at]))
  return candidates
    .map(candidate => position.get(candidate.id) ?? 0)
    .filter(at => at > 0)
    .sort((a, b) => a - b)
    .slice(0, CACHE_MARKS)
}

// The prompt for one replay, `without` naming the block to remove (none for
// the baseline). The removed block is left out entirely, so nothing hints at
// what is missing.
export const replayPrompt = (replay: Replay, marks: readonly number[], without?: string): TextBlock[] => {
  const skipAt = without === undefined ? -1 : replay.segments.findIndex(segment => segment.id === without)
  // Marks past the removed block would sit on text no other replay sends.
  const usable = skipAt < 0 ? marks : marks.filter(at => at <= skipAt)
  const prompt: TextBlock[] = []
  let from = 0
  let head = HEADER
  for (const at of usable) {
    const text = head + replay.segments.slice(from, at).map(segment => segment.text).join('')
    prompt.push({ text, cache: true })
    head = ''
    from = at
  }
  const rest = replay.segments
    .slice(from)
    .filter((_, k) => from + k !== skipAt)
    .map(segment => segment.text)
    .join('')
  prompt.push({
    text:
      head + rest + '</transcript>\n\n' +
      `The user's next message:\n<question>\n${replay.question}\n</question>\n\n` +
      'Reply as the assistant would at this point in the session. Give its answer and ' +
      'the actions it would take, in at most 150 words, with no preamble.',
  })
  return prompt
}

export const promptTokens = (prompt: readonly TextBlock[]): number =>
  prompt.reduce((sum, block) => sum + estimateTokens(block.text), 0)

// What the judge sees: two answers to the same question, labelled neutrally.
export const judgeText = (question: string, a: string, b: string): string =>
  `Question:\n${question}\n\nAnswer A:\n${a}\n\nAnswer B:\n${b}\n\n` +
  'Do A and B reach the same conclusions and propose the same actions? ' +
  'Wording does not matter, substance does.'

export const JUDGE_LABELS = ['same', 'partly different', 'different'] as const
export type JudgeLabel = (typeof JUDGE_LABELS)[number]

export type Verdict = 'needed' | 'partly' | 'unused' | 'failed'

export const verdictOf = (label: string | undefined): Verdict =>
  label === 'different' ? 'needed' : label === 'partly different' ? 'partly' : label === 'same' ? 'unused' : 'failed'

// List prices in dollars per million tokens, for the estimate shown before a
// run. Haiku's are for prompts under 100k tokens, which the size cap keeps to.
export const PRICES: Record<string, { input: number; output: number }> = {
  haiku: { input: 0.1, output: 0.5 },
  sonnet: { input: 2, output: 10 },
}

// A replay's answer is capped at 150 words; this is a little over that.
const ANSWER_TOKENS = 300
// Each judge call reads the question and two answers and names one label.
const JUDGE_INPUT_TOKENS = 1000
const JUDGE_OUTPUT_TOKENS = 10

export type AblationEstimate = { replays: number; promptTokens: number; totalTokens: number; usd?: number }

// What a run would send: the baseline twice, then one replay per candidate.
// Priced as if nothing came from the prompt cache: the replays do mark a
// shared prefix, but how much of it the API serves from cache varies (one live
// run read only a fifth of its input from cache), so this is a ceiling.
export const estimateAblation = (
  replay: Replay,
  candidates: readonly Segment[],
  marks: readonly number[],
  model: string,
): AblationEstimate => {
  const promptSize = promptTokens(replayPrompt(replay, marks))
  const replays = candidates.length + 2
  const price = PRICES[model]
  // One judge call per replay but the first baseline, priced at the replay model's rate.
  const judges = replays - 1
  const usd = price && (
    replays * (promptSize * price.input + ANSWER_TOKENS * price.output) +
    judges * (JUDGE_INPUT_TOKENS * price.input + JUDGE_OUTPUT_TOKENS * price.output)
  ) / 1_000_000
  return { replays, promptTokens: promptSize, totalTokens: replays * promptSize, usd }
}

files.hooks/analyze.ts:
// Pure analysis of the conversation: no `$`, so the tests can feed it
// hand-built messages.

import type { Block, Waste } from '../types'

export type ContentBlock = { type: string; [field: string]: unknown }
export type Message = { role: 'user' | 'assistant'; content: ContentBlock[] }
export type McpTool = { name: string; serverName: string; tokens: number; isLoaded: boolean }

// Roughly four characters per token for English and code. Good enough to rank
// blocks against each other; /context's own figures stay the authority.
export const estimateTokens = (text: string): number => Math.ceil(text.length / 4)

// What the API charges for an image or a PDF page is size dependent; this is a
// typical figure for a screenshot.
const MEDIA_TOKENS = 1600

export const LARGE_OUTPUT_TOKENS = 5000

const FILE_TOOLS = new Set(['Read', 'Edit', 'Write', 'MultiEdit', 'NotebookEdit'])
const EDIT_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit'])

type ToolUse = { name: string; input: Record<string, unknown>; index: number }

const str = (value: unknown): string => (typeof value === 'string' ? value : '')

const clip = (text: string, max: number): string => {
  const flat = text.replace(/\s+/g, ' ').trim()
  return flat.length > max ? flat.slice(0, max - 1) + '…' : flat
}

const normalizePath = (path: string): string => path.replace(/\\/g, '/').toLowerCase()

const shortPath = (path: string): string => {
  const parts = path.replace(/\\/g, '/').split('/').filter(Boolean)
  return parts.slice(-2).join('/')
}

// A one-line name for a tool call, so a list of blocks reads like a log.
export const describeCall = (name: string, input: Record<string, unknown>): string => {
  if (FILE_TOOLS.has(name)) return `${name} ${shortPath(str(input.file_path) || str(input.notebook_path))}`
  if (name === 'Bash' || name === 'PowerShell') return `${name} ${clip(str(input.command), 40)}`
  if (name === 'Grep' || name === 'Glob') return `${name} ${clip(str(input.pattern), 40)}`
  if (name === 'WebFetch') return `WebFetch ${clip(str(input.url), 40)}`
  if (name === 'Agent') return `Agent ${clip(str(input.description), 40)}`
  return name
}

const resultText = (content: unknown): { text: string; media: number } => {
  if (typeof content === 'string') return { text: content, media: 0 }
  if (!Array.isArray(content)) return { text: '', media: 0 }
  let text = ''
  let media = 0
  for (const part of content as ContentBlock[]) {
    if (part.type === 'text') text += str(part.text)
    else if (part.type === 'image' || part.type === 'document') media += 1
  }
  return { text, media }
}

export type Parsed = {
  blocks: Block[]
  // Which call each tool result answers, by tool_use_id.
  calls: Map<string, ToolUse>
  // Where each block sits in the conversation, for "did X happen after Y".
  order: Map<string, number>
}

export const parse = (messages: readonly Message[]): Parsed => {
  const blocks: Block[] = []
  const calls = new Map<string, ToolUse>()
  const order = new Map<string, number>()
  let index = 0

  const push = (block: Block) => {
    blocks.push(block)
    order.set(block.id, index++)
  }

  messages.forEach((message, m) => {
    message.content.forEach((part, b) => {
      const id = `m${m}.${b}`
      if (part.type === 'text') {
        const text = str(part.text)
        const isReminder = message.role === 'user' && text.trimStart().startsWith('<system-reminder>')
        const kind = isReminder ? 'reminder' : message.role === 'user' ? 'prompt' : 'reply'
        const label = isReminder ? 'System reminder' : `${kind === 'prompt' ? 'You' : 'Claude'}: ${clip(text, 50)}`
        push({ id, kind, label, tokens: estimateTokens(text) })
      } else if (part.type === 'thinking') {
        push({ id, kind: 'thinking', label: 'Thinking', tokens: estimateTokens(str(part.thinking)) })
      } else if (part.type === 'tool_use') {
        const name = str(part.name)
        const input = (part.input ?? {}) as Record<string, unknown>
        const useId = str(part.id) || id
        calls.set(useId, { name, input, index })
        push({ id: `${useId}:call`, kind: 'tool-call', label: describeCall(name, input), tokens: estimateTokens(JSON.stringify(input)) })
      } else if (part.type === 'tool_result') {
        const useId = str(part.tool_use_id)
        const call = calls.get(useId)
        const { text, media } = resultText(part.content)
        push({
          id: useId || id,
          kind: 'tool-result',
          label: call ? `${describeCall(call.name, call.input)} result` : 'Tool result',
          tokens: estimateTokens(text) + media * MEDIA_TOKENS,
        })
      } else if (part.type === 'image' || part.type === 'document') {
        push({ id, kind: 'media', label: part.type === 'image' ? 'Image' : 'Document', tokens: MEDIA_TOKENS })
      }
    })
  })

  return { blocks, calls, order }
}

// The Read calls whose results are still in the conversation, by tool_use_id,
// with the file each one read: what the disk check stats.
export const readsInContext = (parsed: Parsed): Map<string, string> => {
  const reads = new Map<string, string>()
  for (const block of parsed.blocks) {
    const call = block.kind === 'tool-result' ? parsed.calls.get(block.id) : undefined
    if (call?.name === 'Read' && str(call.input.file_path)) reads.set(block.id, str(call.input.file_path))
  }
  return reads
}

// Tokens the next request pays for that probably do nothing for the model.
// Each block is counted at most once, under the first rule that claims it.
// `changedOnDisk` names reads whose file changed after they ran, by any means
// (a Bash command, a formatter, an editor), which the transcript cannot show.
export const findWaste = (
  parsed: Parsed,
  mcpTools: readonly McpTool[] = [],
  changedOnDisk: ReadonlySet<string> = new Set(),
  largeOutputTokens = LARGE_OUTPUT_TOKENS,
): Waste[] => {
  const { blocks, calls, order } = parsed
  const waste: Waste[] = []
  const claimed = new Set<string>()

  // `path` compares (case and slashes folded); `shown` is how the call spelled it.
  const reads: { block: Block; key: string; path: string; shown: string; at: number }[] = []
  const editedAt = new Map<string, number[]>()
  for (const [, call] of calls) {
    if (!EDIT_TOOLS.has(call.name)) continue
    const path = normalizePath(str(call.input.file_path) || str(call.input.notebook_path))
    editedAt.set(path, [...(editedAt.get(path) ?? []), call.index])
  }
  for (const block of blocks) {
    if (block.kind !== 'tool-result') continue
    const call = calls.get(block.id)
    if (call?.name !== 'Read') continue
    const path = normalizePath(str(call.input.file_path))
    // The same range of the same file; a different offset is a different read.
    const key = `${path}|${String(call.input.offset ?? '')}|${String(call.input.limit ?? '')}`
    reads.push({ block, key, path, shown: str(call.input.file_path), at: order.get(block.id) ?? 0 })
  }

  // The same file range read more than once: every copy but the newest.
  const byKey = new Map<string, typeof reads>()
  for (const read of reads) byKey.set(read.key, [...(byKey.get(read.key) ?? []), read])
  for (const group of byKey.values()) {
    const first = group[0]
    if (first === undefined || group.length < 2) continue
    const older = group.slice(0, -1)
    older.forEach(read => claimed.add(read.block.id))
    waste.push({
      kind: 'duplicate-read',
      label: `${shortPath(first.shown)} read ${group.length} times`,
      tokens: older.reduce((sum, read) => sum + read.block.tokens, 0),
      blockIds: older.map(read => read.block.id),
    })
  }

  // A read the file has since changed past: the model is holding an old copy.
  for (const read of reads) {
    if (claimed.has(read.block.id)) continue
    const isEdited = (editedAt.get(read.path) ?? []).some(at => at > read.at)
    if (!isEdited && !changedOnDisk.has(read.block.id)) continue
    claimed.add(read.block.id)
    waste.push({
      kind: 'stale-read',
      label: `${shortPath(read.shown)} ${isEdited ? 'edited' : 'changed on disk'} after it was read`,
      tokens: read.block.tokens,
      blockIds: [read.block.id],
    })
  }

  // One tool result big enough to matter on its own.
  for (const block of blocks) {
    if (block.kind !== 'tool-result' || claimed.has(block.id)) continue
    if (calls.get(block.id)?.name === 'Read' || block.tokens < largeOutputTokens) continue
    claimed.add(block.id)
    waste.push({ kind: 'large-output', label: block.label.replace(/ result$/, ''), tokens: block.tokens, blockIds: [block.id] })
  }

  // MCP tool schemas sent every turn for tools this conversation never called.
  const called = new Set([...calls.values()].map(call => call.name))
  const unusedByServer = new Map<string, { tokens: number; count: number }>()
  for (const tool of mcpTools) {
    if (!tool.isLoaded || called.has(tool.name)) continue
    const entry = unusedByServer.get(tool.serverName) ?? { tokens: 0, count: 0 }
    unusedByServer.set(tool.serverName, { tokens: entry.tokens + tool.tokens, count: entry.count + 1 })
  }
  for (const [server, { tokens, count }] of unusedByServer) {
    // Connectors are often named by an id; its first group is enough to tell them apart.
    const name = /^[0-9a-f]{8}-[0-9a-f-]{27}$/i.test(server) ? `${server.slice(0, 8)}…` : server
    waste.push({ kind: 'unused-mcp', label: `${name} · ${count} unused tool${count === 1 ? '' : 's'}`, tokens, blockIds: [] })
  }

  return waste.sort((a, b) => b.tokens - a.tokens)
}

// Scales the per-block estimates so they add up to Claude Code's own count of
// the messages, keeping their ranking. Clamped, so one bad reading cannot
// stretch every block tenfold.
export const calibrate = (blocks: readonly Block[], exactTokens: number | undefined): { blocks: Block[]; factor: number } => {
  const estimated = blocks.reduce((sum, block) => sum + block.tokens, 0)
  if (!exactTokens || estimated === 0) return { blocks: [...blocks], factor: 1 }
  const factor = Math.min(4, Math.max(0.25, exactTokens / estimated))
  return { blocks: blocks.map(block => ({ ...block, tokens: Math.round(block.tokens * factor) })), factor }
}

// A tool call and its result as one row: what a person thinks of as "the Read
// of app.ts", instead of a tiny call block beside a big result block.
export const mergeCalls = (blocks: readonly Block[]): Block[] => {
  const results = new Set(blocks.filter(block => block.kind === 'tool-result').map(block => block.id))
  const callTokens = new Map<string, number>()
  for (const block of blocks) {
    if (block.kind === 'tool-call' && results.has(block.id.replace(/:call$/, ''))) {
      callTokens.set(block.id.replace(/:call$/, ''), block.tokens)
    }
  }
  return blocks
    .filter(block => !(block.kind === 'tool-call' && callTokens.has(block.id.replace(/:call$/, ''))))
    .map(block =>
      block.kind === 'tool-result' && callTokens.has(block.id)
        ? { ...block, label: block.label.replace(/ result$/, ''), tokens: block.tokens + (callTokens.get(block.id) ?? 0) }
        : block)
}

// A transcript's size as the rows `$.session.messages()` returns: text, tool
// inputs and tool results, estimated the same way as the main conversation.
export type TranscriptRow = {
  text: string
  toolUses: readonly { input: Record<string, unknown>; text?: string }[]
  toolResults?: readonly { text: string }[]
}

export const estimateTranscript = (rows: readonly TranscriptRow[]): number =>
  rows.reduce((sum, row) =>
    sum + estimateTokens(row.text) +
    row.toolUses.reduce((uses, use) => uses + estimateTokens(JSON.stringify(use.input)) + estimateTokens(use.text ?? ''), 0) +
    (row.toolResults ?? []).reduce((results, result) => results + estimateTokens(result.text), 0), 0)

// The rows a compaction hands a hook, as far as Drop needs them.
export type CompactRow = {
  toolResults?: readonly { tool_use_id: string; text: string; isError: boolean }[]
  handle?: string
}

// Replaces the named tool results with `stub` and leaves every other message
// exactly as it was, handle and all. A message that changed loses its handle,
// which tells the engine to rebuild it from these fields.
export const stubResults = <R extends CompactRow>(rows: readonly R[], ids: ReadonlySet<string>, stub: string): R[] =>
  rows.map(row => {
    if (!row.toolResults?.some(result => ids.has(result.tool_use_id))) return row
    const { handle: _handle, ...rest } = row
    return {
      ...rest,
      toolResults: row.toolResults.map(result =>
        ids.has(result.tool_use_id) ? { tool_use_id: result.tool_use_id, text: stub, isError: false } : result),
    } as unknown as R
  })

export type Diff = { added: Block[]; addedTokens: number; droppedTokens: number }

// What changed since the last refresh. Blocks keep their ids from one turn to
// the next, so anything new is what this turn added; a compaction shows up as
// a large drop.
export const diff = (previousIds: readonly string[] | undefined, previousTokens: number, blocks: readonly Block[]): Diff => {
  if (previousIds === undefined) return { added: [], addedTokens: 0, droppedTokens: 0 }
  const seen = new Set(previousIds)
  const added = blocks.filter(block => !seen.has(block.id))
  const addedTokens = added.reduce((sum, block) => sum + block.tokens, 0)
  const kept = blocks.reduce((sum, block) => sum + block.tokens, 0) - addedTokens
  return { added, addedTokens, droppedTokens: Math.max(0, previousTokens - kept) }
}

// The breakdown reports auto-compact at the window less a 13k reserve and
// ignores CLAUDE_AUTOCOMPACT_PCT_OVERRIDE, which the compaction check itself
// applies: the lower of that percentage of the window and the usual point.
const AUTOCOMPACT_RESERVE = 13_000

export const autoCompactPoint = (reported: number, overridePercent: string | undefined): number => {
  const percent = Number(overridePercent)
  if (!overridePercent || !Number.isFinite(percent) || percent <= 0 || percent > 100) return reported
  return Math.min(Math.floor((reported + AUTOCOMPACT_RESERVE) * (percent / 100)), reported)
}

export const formatTokens = (tokens: number): string =>
  tokens >= 1_000_000 ? `${(tokens / 1_000_000).toFixed(1)}M`
  : tokens >= 10_000 ? `${Math.round(tokens / 1000)}k`
  : tokens >= 1000 ? `${(tokens / 1000).toFixed(1).replace(/\.0$/, '')}k`
  : String(tokens)

files.hooks/hints.ts:
// Notes for the summarizer when a normal compaction runs. The summary is
// written by a model that sees the transcript but not what this mod measured:
// which files changed, which blocks the last answer leaned on, and which ones
// are old or repeated copies. Telling it keeps the right things in the summary.
//
// Everything here is pure; register.tsx hands the text to session.compact.

import type { Ablation, Waste } from '../types'

const EDIT_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit'])

// How many names each note lists, so the instructions stay short.
const MAX_NAMED = 12

type ToolUse = { tool: string; input: Record<string, unknown> }

// The files the conversation edited, in the order first edited, each once.
export const editedFiles = (uses: readonly ToolUse[]): string[] => {
  const seen = new Map<string, string>()
  for (const use of uses) {
    if (!EDIT_TOOLS.has(use.tool)) continue
    const path = use.input.file_path ?? use.input.notebook_path
    if (typeof path !== 'string' || path === '') continue
    const key = path.replace(/\\/g, '/').toLowerCase()
    if (!seen.has(key)) seen.set(key, path)
  }
  return [...seen.values()]
}

export type HintSources = {
  edited: readonly string[]
  ablation: Ablation | null
  waste: readonly Waste[]
}

const list = (names: readonly string[]) => {
  const shown = names.slice(0, MAX_NAMED).join('; ')
  return names.length > MAX_NAMED ? `${shown}; and ${names.length - MAX_NAMED} more` : shown
}

// What each note covers, for the pane to say before a compaction runs.
export const hintCounts = ({ edited, ablation, waste }: HintSources) => ({
  edited: edited.length,
  needed: ablation?.status === 'done'
    ? ablation.results.filter(result => result.verdict === 'needed' || result.verdict === 'partly').length
    : 0,
  shorten: waste.filter(item => item.blockIds.length > 0).length,
})

// The notes, or undefined when there is nothing worth saying.
export const compactionHints = ({ edited, ablation, waste }: HintSources): string | undefined => {
  const notes: string[] = []
  if (edited.length > 0) {
    notes.push(
      'These files were edited in this session. Keep each one\'s path, what changed in it and why, ' +
      `and any edit still unfinished: ${list(edited)}.`,
    )
  }
  const needed = ablation?.status === 'done'
    ? ablation.results.filter(result => result.verdict === 'needed' || result.verdict === 'partly').map(result => result.label)
    : []
  if (needed.length > 0) {
    notes.push(
      'A replay test found the latest answer depended on these blocks. Keep the facts they ' +
      `contributed, specific values included: ${list(needed)}.`,
    )
  }
  const stale = waste.filter(item => item.kind === 'duplicate-read' || item.kind === 'stale-read').map(item => item.label)
  if (stale.length > 0) {
    notes.push(
      'These file reads are repeated or out of date, since the file changed later. Do not carry ' +
      `their old contents into the summary; at most note that the file was read: ${list(stale)}.`,
    )
  }
  const large = waste.filter(item => item.kind === 'large-output').map(item => item.label)
  if (large.length > 0) {
    notes.push(`These tool outputs were long. Keep one line each with the outcome (passed, failed, the error): ${list(large)}.`)
  }
  if (notes.length === 0) return undefined
  return ['Notes from Context Lens on what this session holds:', ...notes.map(note => `- ${note}`)].join('\n')
}

// The person's own /compact text comes first; the notes follow it.
export const withHints = (instructions: string | undefined, hints: string | undefined): string | undefined =>
  [instructions?.trim(), hints].filter(part => part !== undefined && part !== '').join('\n\n') || undefined

files.hooks/pane.tsx:
// The pane's drawing, apart from the hooks that feed it. Everything here turns
// a snapshot into elements; nothing reads or writes state.

import type { ElementTable, RenderChildren, RenderSurface } from 'claude-code'

import type { Ablation, AblationPlan, AblationResult, AgentRow, Block, History, PaneTab, Snapshot, Waste } from '../types'
import { formatTokens } from './analyze'
import { hintCounts } from './hints'

export type PaneActions = {
  refresh: () => void
  // An ablation is planned first, shown with its cost, then run or cancelled.
  plan: () => void
  run: () => void
  cancel: () => void
  drop: (item: Waste) => void
  setTab: (tab: PaneTab) => void
}

const MUTED = '#8A8F98'
const TEAL = '#3FB6A8'
const AMBER = '#E6A23C'
const ROSE = '#E06C8C'
const BLUE = '#5B9BF0'

const VERDICT_STYLE: Record<AblationResult['verdict'], { text: string; color: string }> = {
  needed: { text: 'needed', color: TEAL },
  partly: { text: 'partly', color: AMBER },
  unused: { text: 'unused', color: MUTED },
  failed: { text: 'failed', color: ROSE },
  pending: { text: '···', color: MUTED },
}

const WASTE_HINT: Record<Waste['kind'], string> = {
  'duplicate-read': 'Re-read',
  'stale-read': 'Stale',
  'large-output': 'Large',
  'unused-mcp': 'Idle MCP',
}

const TABS: { id: PaneTab; label: string; hotkey: string }[] = [
  { id: 'overview', label: 'Overview', hotkey: '1' },
  { id: 'blocks', label: 'Blocks', hotkey: '2' },
  { id: 'ablation', label: 'Ablation', hotkey: '3' },
  { id: 'agents', label: 'Agents', hotkey: '4' },
]

const KNOWN_TOOLS = /^(Read|Edit|Write|MultiEdit|NotebookEdit|Bash|PowerShell|Grep|Glob|WebFetch|Agent) (.+)$/
const MCP_TOOL = /^mcp__(.+?)__(.+)$/

// Fixed columns, in cells, so the numbers and the Drop buttons line up.
const VALUE_COLUMN = 7
const ACTION_COLUMN = 6
const VERDICT_COLUMN = 8

const SPARK = '▁▂▃▄▅▆▇█'
const PARTIAL = ['', '▏', '▎', '▍', '▌', '▋', '▊', '▉']

const sparkline = (percents: readonly number[]) =>
  percents.map(percent => SPARK[Math.min(SPARK.length - 1, Math.floor((percent / 100) * SPARK.length))]).join('')

// A text bar with eighth-cell precision, for the terminal.
const textBar = (fraction: number, cells: number) => {
  const eighths = Math.max(1, Math.round(Math.min(1, fraction) * cells * 8))
  return '█'.repeat(Math.floor(eighths / 8)) + PARTIAL[eighths % 8]
}

// The fill over time as a small area chart, on an absolute 0-100 scale so a
// tall chart always means a full window.
const timelineSvg = (percents: readonly number[], color: string, threshold?: number): string => {
  const W = 300
  const H = 40
  const step = percents.length > 1 ? W / (percents.length - 1) : W
  const y = (percent: number) => (H - 2 - (Math.min(100, percent) / 100) * (H - 4)).toFixed(1)
  const line = percents.map((percent, i) => `${(i * step).toFixed(1)},${y(percent)}`).join(' ')
  const limit = threshold === undefined ? ''
    : `<line x1="0" x2="${W}" y1="${y(threshold)}" y2="${y(threshold)}" stroke="${ROSE}" stroke-width="1" stroke-dasharray="3 3" opacity="0.7"/>`
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="100%" height="${H}" preserveAspectRatio="none">` +
    `<polygon points="0,${H} ${line} ${W},${H}" fill="${color}" fill-opacity="0.18"/>` +
    `<polyline points="${line}" fill="none" stroke="${color}" stroke-width="2" vector-effect="non-scaling-stroke"/>` +
    `${limit}</svg>`
  )
}

const formatUsd = (usd: number) => (usd >= 0.01 ? `$${usd.toFixed(2)}` : '<$0.01')

const percentOf = (part: number, whole: number) => (whole > 0 ? Math.round((part / whole) * 100) : 0)

// Everything the pane draws from, read by the render hook.
export type PaneView = {
  current: Snapshot | null
  tested: Ablation | null
  plan: AblationPlan | null
  past: History
  tab: PaneTab
  // Whether compactions get Context Lens's notes (the compactionHints option).
  hasHints: boolean
}

export const drawPane = (
  els: ElementTable,
  surface: RenderSurface,
  width: number,
  view: PaneView,
  actions: PaneActions,
) => {
  const { current, tested, plan, past, tab, hasHints } = view
  const { Box, Text, Button } = els
  const isTerminal = surface === 'terminal'

  // A label that takes whatever room its row leaves and truncates at the end.
  const fill = (children: RenderChildren) => (
    <Box flexGrow={1} flexShrink={1} overflow="hidden">
      <Text wrap="truncate-end">{children}</Text>
    </Box>
  )

  // "Read src/app.ts" and "wrap_up · ccd_turn" read best with the tool quiet.
  const label = (raw: string) => {
    const text = raw.replace(/ result$/, '')
    const mcp = MCP_TOOL.exec(text.split(' ')[0] ?? '')
    if (mcp) {
      const [, server = '', tool = ''] = mcp
      return <Text>{tool}<Text dimColor>{` · ${server}`}</Text></Text>
    }
    const known = KNOWN_TOOLS.exec(text)
    if (!known) return <Text>{text}</Text>
    const [, tool = '', target = ''] = known
    return <Text><Text dimColor>{tool} </Text>{target}</Text>
  }

  const value = (text: string, color?: string) => (
    <Box width={VALUE_COLUMN} justifyContent="flex-end" flexShrink={0}>
      <Text tabular dimColor={color === undefined} color={color}>{text}</Text>
    </Box>
  )

  const row = (key: string, left: RenderChildren, right: RenderChildren) => (
    <Box key={key} flexDirection="row" gap={1}>
      {fill(left)}
      {right}
    </Box>
  )

  const section = (key: string, title: string, aside: RenderChildren, body: RenderChildren) => (
    <Box key={key} flexDirection="column" marginTop={1}>
      <Box flexDirection="row" justifyContent="space-between">
        <Text weight="semibold" size="footnote">{title}</Text>
        {aside}
      </Box>
      {body}
    </Box>
  )

  const blockRow = (prefix: string, block: Block) =>
    row(`${prefix}-${block.id}`, label(block.label), value(formatTokens(block.tokens)))

  const quiet = (text: string) => <Text dimColor>{text}</Text>

  const tabBar = (
    <Box key="tabs" flexDirection="row" justifyContent="space-between">
      <Box flexDirection="row" gap={1}>
        {TABS.map(({ id, label: name, hotkey }) => {
          const count = id === 'agents' ? current?.agents.length ?? 0 : id === 'blocks' ? current?.waste.length ?? 0 : 0
          return (
            <Button
              key={`tab-${id}`}
              plain
              hotkey={hotkey}
              variant={tab === id ? 'primary' : undefined}
              label={count > 0 ? `${name} ${count}` : name}
              onPress={() => actions.setTab(id)}
            />
          )
        })}
      </Box>
      <Button key="refresh" plain label="↻" onPress={actions.refresh} />
    </Box>
  )

  if (!current) {
    return (
      <Box flexDirection="column">
        {tabBar}
        <Box marginTop={1}>{quiet('Waiting for the first prompt to measure the window.')}</Box>
      </Box>
    )
  }

  const window = current.window || 1
  const used = current.tokens ?? current.categories.reduce((sum, category) => sum + category.tokens, 0)
  const percent = current.percent ?? percentOf(used, window)
  const fillColor = percent >= 85 ? ROSE : percent >= 65 ? AMBER : undefined

  // Overview: the fill, a bar per category, the fill over time, the last turn.
  const compactAt = current.autoCompactAt
  const compactLine = compactAt === undefined ? 'Auto-compact is off'
    : used >= compactAt ? 'Past the auto-compact point'
    : `${formatTokens(compactAt - used)} until auto-compact at ${formatTokens(compactAt)}`

  const biggestCategory = current.categories[0]?.tokens ?? 1
  const barCells = Math.max(10, width - 2)
  const bar = (key: string, fraction: number, color: string) => isTerminal
    ? <Text key={key} color={color}>{textBar(fraction, barCells)}</Text>
    : (
      <Box key={key} width="100%" height={1} backgroundColor="#8A8F981F">
        <Box width={`${Math.max(1, Math.round(Math.min(1, fraction) * 100))}%`} height={1} backgroundColor={color} />
      </Box>
    )

  const header = (
    <Box key="header" flexDirection="column" marginTop={1}>
      <Text>
        <Text size="title" weight="bold" color={fillColor}>{`${percent}%`}</Text>
        <Text dimColor>{`  ${formatTokens(used)} of ${formatTokens(window)}`}</Text>
      </Text>
      <Text dimColor>{compactLine}</Text>
    </Box>
  )

  const bars = (
    <Box key="bars" flexDirection="column">
      {current.categories.map(category => (
        <Box key={`cat-${category.name}`} flexDirection="column" marginTop={1}>
          {row(`cat-row-${category.name}`,
            <Text>{category.name}</Text>,
            <Box flexDirection="row" flexShrink={0}>
              <Text tabular>{formatTokens(category.tokens)}</Text>
              <Box width={5} justifyContent="flex-end"><Text dimColor tabular>{`${percentOf(category.tokens, window)}%`}</Text></Box>
            </Box>)}
          {bar(`cat-bar-${category.name}`, category.tokens / biggestCategory, category.color)}
        </Box>
      ))}
    </Box>
  )

  const lastCost = past.turns.at(-1)
  const sessionUsd = past.turns.reduce((sum, turn) => sum + (turn.usd ?? 0), 0)
  const costLine = lastCost && (() => {
    const sent = lastCost.input + lastCost.cacheRead + lastCost.cacheWrite
    const parts = [`${formatTokens(sent)} in`, `${percentOf(lastCost.cacheRead, sent)}% cached`, `${formatTokens(lastCost.output)} out`]
    if (lastCost.usd !== undefined) parts.push(formatUsd(lastCost.usd))
    return parts.join(' · ')
  })()
  const prompts = `${past.points.length} prompt${past.points.length === 1 ? '' : 's'}`
  const percents = past.points.slice(-Math.max(10, width)).map(point => point.percent)
  const thresholdPercent = compactAt === undefined ? undefined : percentOf(compactAt, window)
  const timeline = percents.length < 2 && !lastCost ? undefined : section(
    'timeline',
    'Over time',
    <Text dimColor tabular>
      {past.compactions.length === 0 ? prompts
        : `${prompts} · ${past.compactions.length} compacted`}
    </Text>,
    <Box flexDirection="column">
      {percents.length >= 2 && (isTerminal || !('Svg' in els)
        ? <Text color={fillColor ?? BLUE}>{sparkline(percents)}</Text>
        : <els.Svg source={timelineSvg(percents, fillColor ?? BLUE, thresholdPercent)} alt={`Window fill over the last ${percents.length} prompts, now ${percent}%`} />)}
      {costLine && row('cost', <Text><Text dimColor>Last prompt </Text>{costLine}</Text>,
        sessionUsd > 0 ? <Text dimColor tabular>{`${formatUsd(sessionUsd)} total`}</Text> : <Text>{''}</Text>)}
    </Box>,
  )

  const added = current.added.filter(block => block.tokens > 0)
  const turnAside = (
    <Text tabular>
      <Text color={TEAL}>{`+${formatTokens(current.addedTokens)}`}</Text>
      {current.droppedTokens > 0 ? <Text color={MUTED}>{`  −${formatTokens(current.droppedTokens)}`}</Text> : ''}
    </Text>
  )
  const lastTurn = section('turn', 'Added by the last prompt', turnAside,
    added.length === 0
      ? quiet('Nothing new since the last refresh.')
      : added.slice(0, 4).map(block => blockRow('added', block)))

  // Blocks: what looks wasted, with Drop, then the biggest blocks.
  const waste = section('waste', 'Likely waste',
    current.wasteTokens > 0 ? <Text tabular color={AMBER}>{formatTokens(current.wasteTokens)}</Text> : quiet('none'),
    current.waste.length === 0
      ? quiet('Nothing flagged.')
      : current.waste.map((item, i) =>
        row(`waste-${i}`,
          <Text><Text color={AMBER}>{`${WASTE_HINT[item.kind]} `}</Text>{item.label}</Text>,
          <Box flexDirection="row" flexShrink={0}>
            {value(formatTokens(item.tokens))}
            <Box width={ACTION_COLUMN} justifyContent="flex-end">
              {item.blockIds.length > 0
                ? <Button key={`drop-${i}`} plain label="Drop" onPress={() => actions.drop(item)} />
                : <Text>{' '}</Text>}
            </Box>
          </Box>)))

  // What a /compact will be told, so the notes are no surprise.
  const hinted = hintCounts({ edited: current.editedFiles, ablation: tested, waste: current.waste })
  const noteParts = [
    hinted.edited > 0 && `keep ${hinted.edited} edited file${hinted.edited === 1 ? '' : 's'}`,
    hinted.needed > 0 && `keep ${hinted.needed} block${hinted.needed === 1 ? '' : 's'} the last answer needed`,
    hinted.shorten > 0 && `drop or shorten ${hinted.shorten} flagged`,
  ].filter((part): part is string => typeof part === 'string')
  const compactNotes = !hasHints ? undefined : section('notes', 'On /compact', undefined,
    quiet(noteParts.length === 0
      ? 'Nothing to add to the summary yet.'
      : `The summary is told to ${noteParts.join(', ')}.`))

  const biggest = section('big', 'Biggest blocks', quiet(`top ${Math.min(8, current.biggest.length)}`),
    current.biggest.length === 0
      ? quiet('The conversation is empty.')
      : current.biggest.filter(block => block.tokens > 0).slice(0, 8).map(block => blockRow('big', block)))

  // Ablation: which blocks the last answer needed.
  const ablateButton = (
    <Button key="ablate" plain label={tested ? '▶ Run again' : '▶ Test blocks'} onPress={actions.plan} />
  )
  const usd = plan?.usd === undefined ? '' : plan.usd < 0.01 ? ', under $0.01' : `, up to $${plan.usd.toFixed(2)}`
  const confirm = plan && (
    <Box key="confirm" flexDirection="column" marginTop={1}>
      <Text>
        {`${plan.replays} replays with ${plan.model}, ${formatTokens(plan.promptTokens)} tokens each`}
        <Text dimColor>{` (${formatTokens(plan.totalTokens)} in all${usd})`}</Text>
      </Text>
      <Box flexDirection="row" gap={2}>
        <Button key="ablate-run" plain variant="primary" label="Run" onPress={actions.run} />
        <Button key="ablate-cancel" plain label="Cancel" onPress={actions.cancel} />
      </Box>
    </Box>
  )
  const counts = (tested?.results ?? []).reduce<Record<string, number>>(
    (tally, result) => ({ ...tally, [result.verdict]: (tally[result.verdict] ?? 0) + 1 }), {})
  const summary = !tested ? undefined
    : tested.status === 'running'
      ? quiet(`Replaying with ${tested.model}: ${tested.results.length - (counts.pending ?? 0)} of ${tested.results.length} done`)
      : tested.status === 'failed'
        ? <Text color={ROSE}>{`Failed: ${tested.message ?? 'unknown error'}`}</Text>
        : (
          <Text>
            {(['needed', 'partly', 'unused'] as const).filter(verdict => counts[verdict]).map((verdict, i) => (
              <Text>
                {i > 0 ? <Text dimColor>{'  ·  '}</Text> : ''}
                <Text color={VERDICT_STYLE[verdict].color}>{`${counts[verdict]} ${verdict}`}</Text>
              </Text>
            ))}
            <Text dimColor>{`  of ${tested.results.length} tested with ${tested.model}`}</Text>
          </Text>
        )
  const ablation = section('relied', 'What the last answer needed',
    tested && tested.status !== 'running' && !plan ? ablateButton : undefined,
    !tested ? (
      <Box flexDirection="column">
        {quiet('Replays your last question with each big block removed, to see which ones the answer needed.')}
        {confirm ?? ablateButton}
      </Box>
    ) : (
      <Box flexDirection="column">
        {confirm}
        {summary}
        <Box flexDirection="column" marginTop={1}>
          {tested.results.map(result =>
            row(`ablate-${result.id}`,
              <Text>{label(result.label)}</Text>,
              <Box flexDirection="row" flexShrink={0}>
                {value(formatTokens(result.tokens))}
                <Box width={VERDICT_COLUMN} justifyContent="flex-end">
                  <Text color={VERDICT_STYLE[result.verdict].color}>{VERDICT_STYLE[result.verdict].text}</Text>
                </Box>
              </Box>))}
        </Box>
        {tested.isNoisy && (
          <Box marginTop={1}>
            <Text color={AMBER}>Two baseline replays disagreed, so the answer varies on its own. Treat these as weak signals.</Text>
          </Box>
        )}
        <Box marginTop={1}>
          {quiet(`Cost ${formatTokens(tested.inputTokens)} in, ${formatTokens(tested.cachedTokens)} cached, ${formatTokens(tested.outputTokens)} out`)}
        </Box>
      </Box>
    ))

  // Agents: what each subagent worked through in its own context, against the
  // report it handed back to this one, and what that work cost.
  const agents = current.agents
  const kept = agents.reduce((sum, agent) => sum + Math.max(0, (agent.workTokens ?? 0) - agent.returnedTokens), 0)
  const processed = agents.reduce((sum, agent) => sum + agent.input + agent.cacheRead, 0)
  const agentRow = (agent: AgentRow) => {
    const model = agent.model ? ` · ${agent.model.replace(/^claude-/, '')}` : ''
    const detail = agent.isRunning
      ? `${agent.agentType ?? 'agent'} · running`
      : `${agent.agentType ?? 'agent'}${model} · processed ${formatTokens(agent.input + agent.cacheRead)} · ${Math.round(agent.durationMs / 1000)}s`
    return (
      <Box key={`agent-${agent.toolUseId}`} flexDirection="column" marginTop={1}>
        {row(`agent-row-${agent.toolUseId}`, <Text>{agent.description}</Text>,
          agent.isRunning ? value('…')
            : <Text tabular>{formatTokens(agent.workTokens ?? 0)}<Text dimColor> → </Text>{formatTokens(agent.returnedTokens)}</Text>)}
        <Text dimColor wrap="truncate-end">{detail}</Text>
      </Box>
    )
  }
  const delegation = section('agents', 'Subagents',
    agents.length > 0 ? <Text tabular color={TEAL}>{`${formatTokens(kept)} kept out`}</Text> : undefined,
    agents.length === 0
      ? quiet('No subagents in this conversation yet.')
      : (
        <Box flexDirection="column">
          {quiet(`Work each did in its own context → what it handed back. ${formatTokens(processed)} processed in all.`)}
          {agents.map(agentRow)}
        </Box>
      ))

  const body = tab === 'blocks' ? [waste, compactNotes, biggest]
    : tab === 'ablation' ? [ablation]
    : tab === 'agents' ? [delegation]
    : [header, bars, timeline, lastTurn]

  return (
    <Box flexDirection="column">
      {tabBar}
      {body}
    </Box>
  )
}

